<?php
require_once __DIR__.'/../config/bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$slug=strtolower(trim((string)($_POST['slug']??'')));if($name&&preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$slug)){$s=db()->prepare('INSERT INTO categories(name,slug,sort_order,is_active) VALUES(?,?,?,1)');$s->execute([$name,$slug,(int)($_POST['sort_order']??0)]);}header('Location: /admin/categories.php');exit;}$rows=db()->query('SELECT * FROM categories ORDER BY sort_order,name')->fetchAll();$pageTitle='Categories — Ikki';require __DIR__.'/../includes/header.php';?><div class="admin-shell"><h1 class="page-title">Categories</h1><nav class="admin-nav"><a href="/admin/">Dashboard</a><a href="/admin/products.php">Products</a><a href="/admin/categories.php">Categories</a></nav><form method="post" class="site-form"><?=csrf_field()?><label class="field-label">Category name</label><input class="field" name="name" required><label class="field-label">URL slug</label><input class="field" name="slug" required placeholder="signature-collection"><label class="field-label">Sort order</label><input class="field" type="number" name="sort_order" value="0"><p><button class="btn">Add category</button></p></form><table class="cart-table"><thead><tr><th>Name</th><th>Slug</th><th>Active</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['slug'])?></td><td><?=(int)$r['is_active']?'Yes':'No'?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../includes/footer.php';?>